query = """select u.email,u.first_name ,u.last_name,a.title , u.company , a.bio , a.share_my_profile ,a.share_my_agenda ,a.profile_image_url ,a.uuid ,u.is_active,(select upper(status) from organizer_status os where id = u.user_status_id) status from attendees a join attendee_conferences ac on ac.attendee_id  = a.id join users u on u.id = a.user_id where ac.conference_id  = (select id from conferences c where "uuid" = :conference_uuid) and a.share_my_profile = true and u.is_archived = false"""